package com.game_manager.gm.workflow; import java.time.Instant; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface WorkflowStepRepository extends JpaRepository<WorkflowStep,UUID>{@Query("select s from WorkflowStep s join fetch s.instance i join fetch i.definitionVersion v join fetch v.definition where s.status='ACTIVE' and ((s.assigneeId=:actor) or (s.assigneeId is null and s.assigneeRole=:role)) order by s.dueAt")List<WorkflowStep> inbox(@Param("actor")UUID actor,@Param("role")String role);Optional<WorkflowStep> findByInstanceIdAndStatus(UUID instance,StepStatus status);List<WorkflowStep> findByInstanceIdOrderByStartedAt(UUID instance);List<WorkflowStep> findByStatusAndReminderAtBeforeAndRemindedAtIsNull(StepStatus status,Instant now);List<WorkflowStep> findByStatusAndDueAtBefore(StepStatus status,Instant now);}
